<?php
namespace Modules\Glitter\Workflow\Services\Runtime;
use InvalidArgumentException;
final class ConditionEvaluator { public function matches(?array $tree,array $data):bool{return $tree===null||$this->node($tree,$data);} private function node(array $n,array $d):bool{if(isset($n['group'])){$c=$n['children']??[];return $n['group']==='all'?array_reduce($c,fn($v,$x)=>$v&&$this->node($x,$d),true):array_reduce($c,fn($v,$x)=>$v||$this->node($x,$d),false);} $f=$n['field']??null;$o=$n['operator']??null;$has=array_key_exists($f,$d);if($o==='exists')return $has;if($o==='not_exists')return !$has;if(!$has)return false;$a=$d[$f];$b=$n['value']??null;return match($o){ 'equals'=>$this->eq($a,$b),'not_equals'=>!$this->eq($a,$b),'in'=>is_array($b)&&in_array($a,$b,true),'not_in'=>is_array($b)&&!in_array($a,$b,true),'greater_than'=>$this->ord($a,$b)>0,'greater_than_or_equal'=>$this->ord($a,$b)>=0,'less_than'=>$this->ord($a,$b)<0,'less_than_or_equal'=>$this->ord($a,$b)<=0,'before'=>$this->date($a)<$this->date($b),'after'=>$this->date($a)>$this->date($b),default=>throw new InvalidArgumentException('Invalid condition operator.')};} private function eq($a,$b):bool{return gettype($a)===gettype($b)&&$a===$b;} private function ord($a,$b):int{if(!is_int($a)||!is_int($b))throw new InvalidArgumentException('Invalid ordered values.');return $a<=>$b;} private function date($v):int{if(!is_string($v)||($t=strtotime($v))===false)throw new InvalidArgumentException('Invalid datetime.');return $t;} }
